    37  static int dynsec__general_config_load(struct dynsec__data *data, cJSON *tree)
    38  {
    39          cJSON *j_default_access;
    40
    41          j_default_access = cJSON_GetObjectItem(tree, "defaultACLAccess");
    42          if(j_default_access && cJSON_IsObject(j_default_access)){
    43                  json_get_bool(j_default_access, ACL_TYPE_PUB_C_SEND, &data->default_access.publish_c_send, true, false);
    44                  json_get_bool(j_default_access, ACL_TYPE_PUB_C_RECV, &data->default_access.publish_c_recv, true, false);
    45                  json_get_bool(j_default_access, ACL_TYPE_SUB_GENERIC, &data->default_access.subscribe, true, false);
    46                  json_get_bool(j_default_access, ACL_TYPE_UNSUB_GENERIC, &data->default_access.unsubscribe, true, false);
    47          }
    48          return MOSQ_ERR_SUCCESS;
    49  }
