    78          if(tree == NULL){
    79                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error loading Dynamic security plugin config: File is not valid JSON.");
    80                  return 1;
    81          }
    82
    83          if(dynsec__general_config_load(data, tree)
    84                          || dynsec_roles__config_load(data, tree)
    85                          || dynsec_clients__config_load(data, tree)
    86                          || dynsec_groups__config_load(data, tree)
    87                          ){
    88
    89                  cJSON_Delete(tree);
    90                  return 1;
    91          }
    92
    93          cJSON_Delete(tree);
    94          return 0;
    95  }
