   152  char *dynsec__config_to_json(struct dynsec__data *data)
   153  {
   154          cJSON *tree;
   155          char *json_str;
   156
   157          tree = cJSON_CreateObject();
   158          if(tree == NULL) return NULL;
   159
   160          if(dynsec__general_config_save(data, tree)
   161                          || dynsec_clients__config_save(data, tree)
   162                          || dynsec_groups__config_save(data, tree)
   163                          || dynsec_roles__config_save(data, tree)){
   164
   165                  cJSON_Delete(tree);
   166                  return NULL;
   167          }
   168
   169          /* Print json to string */
   170          json_str = cJSON_Print(tree);
   171          cJSON_Delete(tree);
   172          return json_str;
   173  }
